// Embeds a held-out validation photo into a gitignored Dart file for the on-device model test.
// Usage: dart run tool/make_test_image.dart <path-to-jpg>
import 'dart:convert';
import 'dart:io';

void main(List<String> args) {
  final bytes = File(args.single).readAsBytesSync();
  File('integration_test/test_image.g.dart').writeAsStringSync(
    '// Generated by tool/make_test_image.dart. Not committed (dataset image).\n'
    "const testImageName = '${args.single.split(RegExp(r'[\\/]')).last}';\n"
    "const testImageBase64 = '${base64Encode(bytes)}';\n",
  );
}
